namespace InventoryApp.Services;

public record EquipmentItem(
    int Id,
    string Name,
    string Location,
    DateTime LastInspected);

public class EquipmentService
{
    private static readonly EquipmentItem[] Items =
    [
        new(1, "Hydraulic Press #4",   "Building A – Bay 2",  new(2026, 5, 12)),
        new(2, "CNC Lathe L-200",      "Building B – Floor 1", new(2026, 6, 3)),
        new(3, "Conveyor Belt C-9",     "Warehouse 3",         new(2026, 4, 28)),
        new(4, "Forklift FL-17",        "Loading Dock",        new(2026, 6, 20)),
        new(5, "Welding Robot WR-3",    "Building A – Bay 5",  new(2026, 3, 15)),
        new(6, "Air Compressor AC-1",   "Utility Room",        new(2026, 6, 1)),
        new(7, "Overhead Crane OC-2",   "Building B – Floor 2", new(2025, 12, 10)),
        new(8, "Band Saw BS-11",        "Workshop",            new(2026, 5, 22)),
    ];

    public async Task<IReadOnlyList<EquipmentItem>> GetAllAsync()
    {
        // Simulate a slow data source
        await Task.Delay(800);
        return Items;
    }
}

@page "/inventory"
@attribute [StreamRendering]
@rendermode InteractiveServer
@inject EquipmentService Svc

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private IReadOnlyList<EquipmentItem>? items;

    protected override async Task OnInitializedAsync()
    {
        items = await Svc.GetAllAsync();
    }
}

